import React from 'react';
import { useAuth } from '../../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import './Settings.css';

const Settings = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  if (!user) {
    return (
      <div className="settings-page">
        <h2>Please log in to see your settings.</h2>
      </div>
    );
  }

  const handleLogout = () => {
    logout();
    navigate('/'); // Redirect to home page after logout
  };

  return (
    <div className="settings-page">
      <div className="settings-container">
        <h2>Settings</h2>
        <div className="profile-details">
          <div className="detail-item">
            <strong>Name:</strong>
            <span>{user.name}</span>
          </div>
          <div className="detail-item">
            <strong>Email:</strong>
            <span>{user.email}</span>
          </div>
        </div>
        <div className="settings-menu">
          <button className="settings-button" onClick={() => navigate('/profile')}>Profile</button>
          <button className="settings-button" onClick={() => navigate('/notifications')}>Notifications</button>
          <button className="settings-button" onClick={() => navigate('/shipping-returns')}>Shipping & Returns</button>
          <button onClick={handleLogout} className="logout-button">
            Logout
          </button>
        </div>
      </div>
    </div>
  );
};

export default Settings;
